if (typeof window !== 'undefined') {
  window.prepareBackupDownloadLink = function(anchorEl) {
    try {
      let dataStr = '';
      if (typeof db !== 'undefined' && typeof db.exportData === 'function') {
        dataStr = db.exportData();
      } else if (typeof db !== 'undefined' && db.state) {
        dataStr = JSON.stringify(db.state, null, 2);
      } else {
        dataStr = '{}';
      }

      const now = new Date();
      const dateStr = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0') + '-' + String(now.getDate()).padStart(2,'0');
      const fileName = `THCS_AmaTrangLong_Backup_CSDL_${dateStr}.json`;

      const blob = new Blob([dataStr], { type: 'application/json;charset=utf-8' });
      const blobUrl = URL.createObjectURL(blob);

      if (anchorEl) {
        anchorEl.href = blobUrl;
        anchorEl.download = fileName;
      }
      return blobUrl;
    } catch(e) {
      console.error('prepareBackupDownloadLink error:', e);
      return '#';
    }
  };

  window.triggerDirectBackupDownload = function(linkEl, evt) {
    try {
      window.prepareBackupDownloadLink(linkEl);
      if (window.app && typeof window.app.showToast === 'function') {
        window.app.showToast('✅ Đã xuất file Sao lưu CSDL (.json) về máy thành công!');
      } else {
        alert('✅ Đã xuất file Sao lưu CSDL (.json) về máy thành công!');
      }
    } catch(e) {
      console.error('triggerDirectBackupDownload error:', e);
    }
  };
  window.downloadJSONBackup = window.triggerDirectBackupDownload;
}

