  exportUsersExcel() {
    const users = db.state.users || [];
    const bom = new Uint8Array([0xEF, 0xBB, 0xBF]);
    const csvText = "STT,Tên cán bộ,Tên đăng nhập,Nhóm người dùng,Trạng thái\n" + 
      users.map((u, idx) => (idx + 1) + ',"' + u.name + '",' + u.username + ',' + u.groupId + ',' + u.status).join('\n');
    
    const blob = new Blob([bom, csvText], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "Danh_sach_nguoi_dung_THCS_Ama_Trang_Long.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 1000);

    this.showToast('📊 Đã xuất file tệp danh sách người dùng Excel (.csv) thành công!');
  }

