    if (!name) return;

    const teachers = db.getTeachers ? (db.getTeachers() || []) : [];
    const teacherNames = ['Chu Văn Giáp', 'Cao Thị Ngọc Châu', 'Trần Thanh Xuân', 'Lê Thị Liên Hương', 'Nông Văn Dũng'];
    teachers.forEach(t => { if (t.name && !teacherNames.includes(t.name)) teacherNames.push(t.name); });
    const teacherListStr = teacherNames.map((tn, idx) => (idx + 1) + '. ' + tn).join('\n');

    const teacherChoice = prompt('Chọn Giáo viên chủ nhiệm cho lớp ' + name + ':\n\n' + teacherListStr + '\n\nNhập tên Giáo viên chủ nhiệm:', teacherNames[0]);
    if (!teacherChoice) return;

    if (!db.state.classesList) db.state.classesList = [];
    const newC = {
      id: 'cls_' + Date.now(),
      grade: grade,
      name: name,
      homeroomTeacher: teacherChoice,
      studentCount: 35
    };
    db.state.classesList.push(newC);
