        const nameMatch = (r.itemName || '').toLowerCase().includes(kw);
        const typeMatch = (r.itemType || '').toLowerCase().includes(kw);
        const userMatch = (r.deletedBy || '').toLowerCase().includes(kw);
        return nameMatch || typeMatch || userMatch;
