    ctx.arc(eyeSpacing - eyeRadius*0.3, eyeY - eyeRadius*0.3, eyeRadius*0.4, 0, Math.PI * 2);
    ctx.arc(eyeSpacing + eyeRadius*0.3, eyeY + eyeRadius*0.2, eyeRadius*0.2, 0, Math.PI * 2);
    ctx.fill();

    // Rosy Pink Blushing Cheeks
    ctx.fillStyle = 'rgba(255, 133, 161, 0.75)';
    ctx.beginPath();
    ctx.ellipse(-eyeSpacing - eyeRadius*0.8, eyeY + eyeRadius*1.1, eyeRadius*0.8, eyeRadius*0.45, 0, 0, Math.PI * 2);
    ctx.ellipse(eyeSpacing + eyeRadius*0.8, eyeY + eyeRadius*1.1, eyeRadius*0.8, eyeRadius*0.45, 0, 0, Math.PI * 2);
    ctx.fill();

    // Open Happy Smile with Tooth & Tongue
    ctx.fillStyle = '#991b1b';
    ctx.beginPath();
    ctx.arc(0, eyeY + eyeRadius*0.7, eyeRadius*0.9, 0, Math.PI);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-eyeRadius*0.35, eyeY + eyeRadius*0.7, eyeRadius*0.7, eyeRadius*0.35);

    ctx.fillStyle = '#f43f5e';
    ctx.beginPath();
    ctx.arc(0, eyeY + eyeRadius*1.2, eyeRadius*0.45, Math.PI, Math.PI * 2);
    ctx.fill();

    // Draw Cute Chibi Arms & Legs (Matching user photo!)
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';

    // Left Arm (Raised Up)
    ctx.beginPath();
    ctx.moveTo(-r * 0.8, 0);
